import os

def delete_files(directory, extension, permanent=False):

    # Check if the directory exists

    if not os.path.isdir(directory):

        print("The specified directory does not exist.")

        return

    # Loop through all the files in the directory

    for file in os.listdir(directory):

        # Check if the file has the specified extension

        if file.endswith(extension):

            # If permanent is True, delete the file permanently

            if permanent:

                os.remove(os.path.join(directory, file))

            else:

                os.remove(file)

    print("All files with the specified extension have been deleted.")


# Example usage

delete_files('/home/user/Desktop', '.txt', permanent=True)

